#!/usr/bin/env python3
"""2026-10-28 AMDC audit corrections to the generated site (deterministic).

Runs AFTER session2_site + build_site_thcs inside scripts/build_site.py main().
It does not touch the session-2 generator: it applies evidence-driven,
anchor-asserted corrections to the generated bytes, rewrites the two
machine-readable decision files to the SGCE authority, refreshes the AMDC
JSON copies, rewrites how-to-submit.html onto the cleared file, and writes
the AMDC lane dossier. Every replacement asserts its anchor count (fail
closed); output is a pure function of committed evidence/.
"""
from __future__ import annotations

import hashlib
import json
import re
import shutil
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
DOCS = ROOT / "docs"


def load(name: str) -> dict:
    return json.loads((ROOT / "evidence" / name).read_text())


def sha_of(path: Path) -> str:
    return hashlib.sha256(path.read_bytes()).hexdigest()


def sub_once(text: str, old: str, new: str, where: str) -> str:
    n = text.count(old)
    assert n == 1, f"{where}: anchor found {n}x, expected 1: {old[:90]!r}"
    return text.replace(old, new, 1)


def resub_once(text: str, pattern: str, new: str, where: str) -> str:
    found = re.findall(pattern, text, flags=re.S)
    assert len(found) == 1, f"{where}: regex found {len(found)}x, expected 1: {pattern[:90]!r}"
    return re.sub(pattern, new, text, count=1, flags=re.S)


FOCUS_IDS = ["32", "36", "28", "31", "33", "25", "30", "24", "27"]


def audit_section(slope: float, intercept: float, ranking: list) -> str:
    r = {row["id"]: row for row in ranking}

    def proj(h: float) -> str:
        return f"{intercept + slope * h:.4f}"

    def frow(site: str) -> str:
        row = r[f"focus:GEMSDOE{site}"]
        h = row["holdout_dti"]
        return (
            f"<tr><td>GEMSDOE{site} (pinned above)</td><td>{row['owner_reported']}</td>"
            f"<td>{h:.4f}</td><td>{proj(h)} ±0.005</td>"
            f"<td>registered raster — reference only</td><td>—</td></tr>"
        )

    sgce = r["WBG-sgce"]["holdout_dti"]
    repo = {
        "TDE-30k": ("WBG-tde30k", "0.723 — FAIL", "EXCLUDED — duplicate; revoked as gate candidate"),
        "skarpline": ("WBG-skarpline", "0.772 — FAIL", "EXCLUDED — duplicate"),
        "CSPES": ("WBG-cspes", "0.703 — FAIL", "EXCLUDED — duplicate"),
        "HCE1": ("WBG-hce1", "0.741 — FAIL", "EXCLUDED — duplicate"),
    }
    repo_rows = "".join(
        f"<tr><td>{name} (research artifact)</td><td>—</td><td>{r[k]['holdout_dti']:.4f}</td>"
        f"<td>{proj(r[k]['holdout_dti'])} ±0.005</td><td>max gated overlap {ov}</td><td>{dec}</td></tr>"
        for name, (k, ov, dec) in repo.items()
    )
    e3 = 0.05522515712089214
    return f"""<section class="section" id="bytes-audit"><div class="section-head"><div><div class="kicker">Independent bytes audit · 2026-10-28</div><h2>Shipped-bytes audit: what each file actually measures</h2><p>The 2026-10-27 SGCE headline (0.1675) was measured on per-cell rebuild files, not on the downloadable bytes. Every number below was re-scored from shipped bytes on identical folds. Full records: <a href="data/sgce_bytes_audit.json">bytes audit ↓</a> · <a href="data/amdc_run_card.json">AMDC run card ↓</a> · <a href="amdc/index.html">AMDC lane dossier →</a></p></div></div><div class="card table-card" tabindex="0"><table><thead><tr><th>File</th><th>Owner-reported</th><th>Shipped-bytes holdout (audited)</th><th>Projection ±0.005</th><th>Uniqueness (134-row registry)</th><th>Decision</th></tr></thead><tbody><tr><td><strong>SGCE (this download)</strong></td><td>—</td><td><strong>0.0191 native v3.0</strong> [0.0169–0.0211] · 0.0190 matched v2 [0.0171–0.0208] · B2 bytes 0.0045 / 0.0039</td><td><strong>{proj(sgce)}</strong> ±0.005</td><td>max gated overlap 0.690 — <strong>PASS</strong>; literal dupes only the dense control + self-aliases</td><td><strong>SUBMIT-WITH-CAVEAT</strong></td></tr>{''.join(frow(s) for s in FOCUS_IDS)}{repo_rows}<tr><td>AMDC-E3 (this audit's build)</td><td>—</td><td>{e3:.4f} [0.0415–0.0707]</td><td>{proj(e3)} ±0.005</td><td>max gated overlap 0.936 — FAIL (25 literal dupes)</td><td>EXCLUDED — duplicate-stop; no TIF written</td></tr></tbody></table></div><p class="note"><strong>How to read this table.</strong> Holdout = pooled HOLDOUT-DTI on identical withheld folds (native: GEMSDOE32-HIDE-RECOVER-v3.0, 22,232 withheld; matched: gems57-pooled-hide-v2, 22,893 withheld). Projection = OLS of owner-reported on matched holdout over the 9 focus rasters (R² 0.786, LOOCV 0.005); it is weak out-of-family and disagrees with the session-2 ledger PROJECTION (0.0669) and the RFL LEDGER-INVERSION ESTIMATE class (0.21–0.27 for TDE-30k) — the span across methods is the uncertainty statement, and no projection is a score. Owner reports and holdouts are inverted on the 9 focus sites (Spearman −0.849, Pearson −0.886); GEMSDOE25/30 are holdout-identical under separate reports. Uniqueness limit: 0.70 gated overlap, 0.90 |ρ|, no exact duplicates.</p></section>"""


HOLDOUT_DD_NEW = (
    "<dt>HOLDOUT-DTI</dt><dd><strong>0.0191</strong> shipped bytes (95% spatial-cluster CI "
    "0.0169–0.0211), evaluator GEMSDOE32-HIDE-RECOVER-v3.0, 22,232 withheld positives — "
    "re-scored 2026-10-28 from the downloadable file on the identical folds. Cross-check: "
    "0.0190 [0.0171–0.0208] on gems57-pooled-hide-v2 (22,893 withheld). B2 reference bytes: "
    "0.0045 / 0.0039 (shipped-bytes Δ +0.0146). The earlier 0.1675 figure was measured on "
    "per-cell rebuild files with asymmetric per-domain budgets, not on these bytes "
    "(budget-repaired pooled rebuild: 0.0026); it is retained only as a labelled method "
    "measurement. See <a href=\"#bytes-audit\">bytes audit</a>.</dd>"
)

ESTIMATE_APPEND = (
    " <em>Independent cross-check 2026-10-28:</em> a matched-holdout OLS over the 9 focus "
    "rasters (R² 0.786, LOOCV 0.005) projects <strong>0.2726 ±0.005</strong> for the shipped "
    "bytes — while this ledger PROJECTION says 0.0669 and the RFL LEDGER-INVERSION ESTIMATE "
    "class said 0.21–0.27 for TDE-30k. The methods disagree with each other; the span is the "
    "uncertainty. No projection is a score."
)

UNIQUENESS_APPEND = (
    " <em>Re-confirmed 2026-10-28</em> on the 134-row hash-verified registry: max gated "
    "overlap 0.690 vs GEMSDOE77, max non-self |ρ| 0.075 (dense-control ρ 0.080), literal "
    "dupes only the universal dense control plus the zeros/nan self-aliases."
)


def patch_pages(section_html: str) -> None:
    pages = ["index.html", "executive-summary.html", "research.html", "evidence.html"]
    texts = {p: (DOCS / p).read_text() for p in pages}

    for p in pages:
        texts[p] = resub_once(
            texts[p], r"<dt>HOLDOUT-DTI</dt><dd>.*?</dd>", HOLDOUT_DD_NEW, f"{p} holdout dd"
        )
        texts[p] = resub_once(
            texts[p],
            r"(<dt>Score estimate</dt><dd>.*?)</dd>",
            r"\1" + ESTIMATE_APPEND + "</dd>",
            f"{p} estimate dd",
        )
        texts[p] = resub_once(
            texts[p],
            r"(<dt>Uniqueness</dt><dd>.*?)</dd>",
            r"\1" + UNIQUENESS_APPEND + "</dd>",
            f"{p} uniqueness dd",
        )

    idx = texts["index.html"]
    idx = sub_once(
        idx,
        "SGCE beats the 0.2778 reference on a matched hide-and-recover holdout.",
        "SGCE shipped bytes beat the 0.2778 reference bytes 4–5× on two matched "
        "hide-and-recover holdouts (0.0191 vs 0.0045; 0.0190 vs 0.0039).",
        "index subhead",
    )
    idx = sub_once(
        idx,
        '<span class="stat-label">HOLDOUT-DTI (new file)</span><strong>0.1675</strong>'
        "<small>CI 0.1524–0.1820</small>",
        '<span class="stat-label">HOLDOUT-DTI (shipped bytes)</span><strong>0.0191</strong>'
        "<small>CI 0.0169–0.0211 · native evaluator</small>",
        "index stat holdout",
    )
    idx = sub_once(
        idx,
        '<span class="stat-label">Champion proxy (same folds)</span><strong>0.0992</strong>'
        "<small>paired Δ +0.0683</small>",
        '<span class="stat-label">B2 reference bytes (same folds)</span><strong>0.0045</strong>'
        "<small>shipped-bytes Δ +0.0146</small>",
        "index stat champion",
    )
    idx = sub_once(
        idx,
        "Result: <strong>0.1675</strong> vs <strong>0.0992</strong> HOLDOUT-DTI on identical folds.",
        "Result on per-cell rebuilds: <strong>0.1675</strong> vs <strong>0.0992</strong> "
        "HOLDOUT-DTI on identical folds; shipped bytes re-scored "
        "<strong>0.0191</strong> vs <strong>0.0045</strong> (see bytes audit).",
        "index result card",
    )
    idx = sub_once(
        idx,
        "The released file wins the matched holdout by +0.0683 but the "
        "ledger-calibrated projection is only 0.0669.",
        "Per-cell rebuilds won the matched holdout by +0.0683 and the ledger-calibrated "
        "projection was 0.0669; the shipped bytes re-scored 0.0191 on the identical "
        "evaluator while an independent matched-holdout OLS projects 0.2726 ±0.005 — "
        "the disagreement between estimates is itself the uncertainty (see bytes audit).",
        "index disagreement note",
    )
    texts["index.html"] = idx

    ex = texts["executive-summary.html"]
    ex = sub_once(
        ex,
        "On the identical 8-cell, whole-segment, 1.5 km-collar holdout it reaches "
        "<strong>0.1675</strong> (95% CI 0.1524–0.1820) vs <strong>0.0992</strong>, "
        "paired Δ +0.0683 with CI entirely above zero.",
        "On the identical 8-cell, whole-segment, 1.5 km-collar holdout the per-cell rebuilds "
        "reached <strong>0.1675</strong> (95% CI 0.1524–0.1820) vs <strong>0.0992</strong>, "
        "paired Δ +0.0683 with CI entirely above zero — but the shipped bytes re-scored "
        "<strong>0.0191</strong> [0.0169–0.0211] on the identical evaluator and folds, vs "
        "<strong>0.0045</strong> for the B2 reference bytes (see bytes audit).",
        "executive why section",
    )
    texts["executive-summary.html"] = ex

    ev = texts["evidence.html"]
    ev = sub_once(
        ev,
        "<td>+0.0683 (CI 0.0517–0.0855)</td>",
        "<td>+0.0683 (CI 0.0517–0.0855) on per-cell rebuilds; shipped bytes +0.0146 "
        "over B2 bytes (see bytes audit)</td>",
        "evidence G6 row",
    )
    texts["evidence.html"] = ev

    section_anchors = {
        "index.html": ("that is not our score.</p>", "after"),
        "executive-summary.html": (
            '<section class="section" id="irregularities">', "before"
        ),
        "research.html": (
            '<section class="section"><div class="section-head"><div>'
            '<div class="kicker">Official sources verified this session</div>',
            "before",
        ),
        "evidence.html": (
            '<section class="section"><div class="section-head"><div>'
            '<div class="kicker">Evidence hierarchy</div>',
            "before",
        ),
    }
    for p, (anchor, mode) in section_anchors.items():
        assert texts[p].count(anchor) == 1, f"{p}: audit-table anchor"
        if mode == "after":
            texts[p] = texts[p].replace(anchor, anchor + section_html, 1)
        else:
            texts[p] = texts[p].replace(anchor, section_html + anchor, 1)

    for p in pages:
        (DOCS / p).write_text(texts[p], encoding="utf-8")


HOWTO_TEMPLATE = """<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="gemsdoe-decision" content="SUBMIT-WITH-CAVEAT"><title>How to submit · GEMS Field Notes</title><link rel="stylesheet" href="assets/styles.css"></head><body><div class="wrap" style="padding:32px 0;max-width:860px"><p><a href="executive-summary.html">← Executive summary</a> · <a href="index.html">Overview</a> · <a href="amdc/index.html">AMDC audit dossier</a></p><h1>OK TO DOWNLOAD AND SUBMIT — one new unique TIF</h1><p><strong>Cleared file:</strong> <code>{name}</code><br><strong>SHA-256:</strong> <code>{sha}</code><br><strong>Submission note ({note_len} chars, limit 140):</strong> <code>{note}</code></p><p class="mini">Decision SUBMIT-WITH-CAVEAT. The shipped bytes passed an independent format re-check (single float32 band, CRS/shape/transform match, finite values in [0,1], 102,208 dots) and a 134-row registry re-audit (max gated overlap 0.690 — PASS). HOLDOUT-DTI is not a score and these are not organizer scores. Prior lanes used a LEDGER-INVERSION ESTIMATE for their own files; this file's estimate is a labelled PROJECTION (0.0669 ledger / 0.2726 matched-holdout OLS — the methods disagree, and the span is the uncertainty).</p><h2>Exact steps (no judgement calls)</h2><ol><li>Check the weekly slot on the <a href="https://www.drivendata.org/competitions/306/competition-doe-gems/">competition page ↗</a>. If no slot is free, stop — do not upload.</li><li>Download the cleared file: <a href="downloads/{name}" download>↓ {name}</a> (or the <a href="downloads/{stem}-zeros.zip" download>ZIP ↓</a>). Verify the SHA-256 above matches your download.</li><li>Upload exactly that file. Do NOT upload the NaN-outside variant (<code>{stem}-nan.tif</code>): NaN outside the footprint trips the portal validator (“Predicted values must be in range [0, 1]”). Do NOT upload any older research artifact in <a href="downloads/index.html">downloads/</a> — they are labelled DO NOT SUBMIT.</li><li>Paste the {note_len}-character note above verbatim into the submission comment field.</li><li>Submit, then save the receipt (score + submission id + bytes hash). Without a receipt nothing here becomes organizer-confirmed.</li></ol><h2>Revoked predecessor</h2><p class="mini">The 2026-10-27 release gate pointed at TDE-30k (<code>wbggems3-tde30k-tomography-emission-20261027T1853Z-e756a162-zeros.tif</code>). Those bytes are format-valid but fail full-registry uniqueness (max gated overlap 0.723 &gt; 0.70) and are revoked as the gate candidate. The gate now points at the SGCE bytes above; the TDE-30k run card stays in <a href="data/candidate_run_card.json">data/candidate_run_card.json</a> as that lane's historical record.</p></div></body></html>
"""


def write_howto(card: dict, build: dict) -> None:
    zero = next(k for k in build["files"] if k.endswith("-zeros.tif"))
    stem = zero[: -len("-zeros.tif")]
    assert card["submission_name"] == stem
    note = card["submission_note"]
    assert 0 < len(note) <= 140, "submission note exceeds the 140-char portal limit"
    (DOCS / "how-to-submit.html").write_text(
        HOWTO_TEMPLATE.format(name=zero, stem=stem, sha=build["files"][zero]["sha256"],
                              note=note, note_len=len(note)),
        encoding="utf-8",
    )


